// 1. Trích xuất và chuẩn hóa event từ RabbitMQ message
const raw = $input.first().json;
let payload = {};

if (raw.content) {
  if (typeof raw.content === 'string') {
    try {
      payload = JSON.parse(raw.content);
    } catch (e) {
      payload = { text: raw.content };
    }
  } else if (typeof raw.content === 'object') {
    payload = raw.content;
  }
} else {
  payload = raw;
}

const data = payload.data || payload;
const workflowRunId = data.workflowRunId || payload.workflowRunId || null;
const scope = data.scope || payload.scope || 'ALL';
const filter = data.filter || payload.filter || null;
const triggeredByUserId = data.triggeredByUserId || payload.triggeredByUserId || null;

if (!workflowRunId) {
  throw new Error('Event missing required workflowRunId parameter');
}

return [{
  json: {
    workflowRunId,
    scope,
    filter,
    triggeredByUserId,
    receivedAt: new Date().toISOString()
  }
}];

// Rule Engine: Kiểm tra chất lượng dữ liệu và phát hiện trùng lặp
const response = $input.first().json;
const meta = $('⚙️ Normalize Event').first().json;
const leads = response.leads || [];

const findings = [];
const ambiguousCases = [];

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// 1. Phân tích trùng lặp Lead trong batch (Email & Phone)
const emailMap = new Map();
const phoneMap = new Map();

for (const lead of leads) {
  if (lead.email) {
    const cleanEmail = lead.email.trim().toLowerCase();
    if (!emailMap.has(cleanEmail)) emailMap.set(cleanEmail, []);
    emailMap.get(cleanEmail).push(lead);
  }
  if (lead.phone) {
    const cleanPhone = lead.phone.replace(/[^0-9+]/g, '');
    if (cleanPhone.length >= 8) {
      if (!phoneMap.has(cleanPhone)) phoneMap.set(cleanPhone, []);
      phoneMap.get(cleanPhone).push(lead);
    }
  }
}

// Ghi nhận duplicate candidates (safeToApply: false vì KHÔNG được tự động xóa/gộp mà phải do con người quyết định)
for (const [email, duplicateLeads] of emailMap.entries()) {
  if (duplicateLeads.length > 1) {
    for (const lead of duplicateLeads) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: `${lead.firstName || ''} ${lead.lastName || ''} (${lead.email})`.trim(),
        fieldName: 'email',
        issueType: 'DUPLICATE_CANDIDATE',
        severity: 'CRITICAL',
        currentValue: lead.email,
        proposedValue: `Duplicate conflict with ${duplicateLeads.length - 1} other record(s)`,
        confidence: 0.99,
        reason: `Lead shares exact email with other leads in database. Requires manual review.`,
        safeToApply: false,
        requiresHumanApproval: true
      });
    }
  }
}

for (const [phone, duplicateLeads] of phoneMap.entries()) {
  if (duplicateLeads.length > 1) {
    for (const lead of duplicateLeads) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: `${lead.firstName || ''} ${lead.lastName || ''} (${lead.email})`.trim(),
        fieldName: 'phone',
        issueType: 'DUPLICATE_CANDIDATE',
        severity: 'HIGH',
        currentValue: lead.phone,
        proposedValue: `Duplicate phone conflict with ${duplicateLeads.length - 1} other record(s)`,
        confidence: 0.95,
        reason: `Lead shares same normalized phone number (${phone}). Requires manual review.`,
        safeToApply: false,
        requiresHumanApproval: true
      });
    }
  }
}

// 2. Rule checks trên từng Lead
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

for (const lead of leads) {
  const leadName = `${lead.firstName || ''} ${lead.lastName || ''}`.trim() || 'Unnamed Lead';
  const leadIdent = `${leadName} (${lead.email || 'No email'})`;

  // a. Missing mandatory fields
  if (!lead.firstName || !lead.firstName.trim()) {
    findings.push({
      id: uuidv4(),
      recordType: 'Lead',
      recordId: lead.id,
      leadIdentifier: leadIdent,
      fieldName: 'firstName',
      issueType: 'MISSING_FIELD',
      severity: 'HIGH',
      currentValue: lead.firstName || null,
      proposedValue: null,
      confidence: 1.0,
      reason: 'First name is a required field but is currently missing or blank.',
      safeToApply: false,
      requiresHumanApproval: true
    });
  }

  // b. Email validation & normalization
  if (lead.email) {
    const rawEmail = lead.email;
    const trimmed = rawEmail.trim();
    const lower = trimmed.toLowerCase();

    if (rawEmail !== trimmed) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: leadIdent,
        fieldName: 'email',
        issueType: 'WHITESPACE_TRIM',
        severity: 'LOW',
        currentValue: rawEmail,
        proposedValue: lower,
        confidence: 1.0,
        reason: 'Email contains leading or trailing whitespace.',
        safeToApply: true,
        requiresHumanApproval: true
      });
    } else if (rawEmail !== lower) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: leadIdent,
        fieldName: 'email',
        issueType: 'CASE_NORMALIZATION',
        severity: 'LOW',
        currentValue: rawEmail,
        proposedValue: lower,
        confidence: 1.0,
        reason: 'Email contains uppercase characters. Standard convention is lowercase.',
        safeToApply: true,
        requiresHumanApproval: true
      });
    }

    if (!emailRegex.test(lower)) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: leadIdent,
        fieldName: 'email',
        issueType: 'INVALID_EMAIL',
        severity: 'HIGH',
        currentValue: rawEmail,
        proposedValue: null,
        confidence: 0.98,
        reason: 'Email address does not match standard RFC email format.',
        safeToApply: false,
        requiresHumanApproval: true
      });
    }
  }

  // c. Website formatting
  if (lead.companyWebsite) {
    const rawWeb = lead.companyWebsite.trim();
    if (rawWeb && !/^https?:\/\//i.test(rawWeb)) {
      const cleanWeb = 'https://' + rawWeb.replace(/^www\./i, '').replace(/\/+$/, '');
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: leadIdent,
        fieldName: 'companyWebsite',
        issueType: 'INVALID_WEBSITE',
        severity: 'LOW',
        currentValue: lead.companyWebsite,
        proposedValue: cleanWeb,
        confidence: 0.95,
        reason: 'Company website is missing standard https:// protocol prefix.',
        safeToApply: true,
        requiresHumanApproval: true
      });
    }
  }

  // d. Phone formatting consistency
  if (lead.phone) {
    const rawPhone = lead.phone.trim();
    const cleanedDigits = rawPhone.replace(/[^0-9+]/g, '');
    if (rawPhone !== cleanedDigits && cleanedDigits.length >= 9) {
      findings.push({
        id: uuidv4(),
        recordType: 'Lead',
        recordId: lead.id,
        leadIdentifier: leadIdent,
        fieldName: 'phone',
        issueType: 'INCONSISTENT_PHONE',
        severity: 'LOW',
        currentValue: rawPhone,
        proposedValue: cleanedDigits,
        confidence: 0.92,
        reason: 'Phone contains formatting noise or symbols. Normalized to clean dialable digits.',
        safeToApply: true,
        requiresHumanApproval: true
      });
    }
  }

  // e. Candidate for AI analysis: Inconsistency between companyName and website or domain
  if (lead.companyName && lead.companyWebsite) {
    const domain = lead.companyWebsite.replace(/^(?:https?:\/\/)?(?:www\.)?/i, '').split('/')[0].split('.')[0].toLowerCase();
    const comp = lead.companyName.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (domain.length > 3 && comp.length > 3 && !comp.includes(domain) && !domain.includes(comp)) {
      ambiguousCases.push({
        recordId: lead.id,
        leadIdentifier: leadIdent,
        companyName: lead.companyName,
        companyWebsite: lead.companyWebsite,
        email: lead.email
      });
    }
  }
}

return [{
  json: {
    workflowRunId: meta.workflowRunId,
    totalLeadsScanned: leads.length,
    ruleFindings: findings,
    ambiguousCases: ambiguousCases.slice(0, 10),
    leadsCount: leads.length
  }
}];

const prep = $input.first().json;

const cases = prep.ambiguousCases || [];
if (cases.length === 0) {
  return [{
    json: {
      workflowRunId: prep.workflowRunId,
      totalLeadsScanned: prep.totalLeadsScanned,
      ruleFindings: prep.ruleFindings,
      aiProposals: []
    }
  }];
}

const prompt = `
You are an enterprise AI Data Cleaning Specialist for a CRM system.
Analyze the following leads where company names and website domains appear inconsistent:

${JSON.stringify(cases, null, 2)}

Instructions:
1. Identify if the discrepancy is due to abbreviations, brand variants, or obvious typos.
2. STRICT RULE: DO NOT hallucinate, fabricate, or guess any missing phone numbers, personal emails, or contact identities.
3. Only propose high-confidence cleanups for company name or website if there is a clear rational alignment.
4. If confident, provide confidence (0.70 to 0.95), proposedValue, reason, and set safeToApply to true or false.

Respond ONLY in this JSON format:
{
  "proposals": [
    {
      "recordId": "lead-uuid",
      "fieldName": "companyName" | "companyWebsite",
      "proposedValue": "string",
      "confidence": 0.85,
      "reason": "Rationale explaining correlation",
      "safeToApply": false
    }
  ]
}
`;

return [{
  json: {
    workflowRunId: prep.workflowRunId,
    totalLeadsScanned: prep.totalLeadsScanned,
    ruleFindings: prep.ruleFindings,
    prompt
  }
}];

// Hợp nhất kết quả từ Rule Engine và Gemini AI, kiểm tra schema hợp đồng
const geminiRes = $input.first().json;
const prep = $('🧠 Synthesize AI Prompt').first().json;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const allFindings = [...(prep.ruleFindings || [])];

// Xử lý AI proposals nếu có
if (geminiRes && !geminiRes.error && geminiRes.candidates) {
  try {
    const text = geminiRes.candidates[0]?.content?.parts?.[0]?.text || '{}';
    const parsed = JSON.parse(text);
    const proposals = parsed.proposals || [];

    for (const p of proposals) {
      if (p.recordId && p.fieldName && p.proposedValue) {
        allFindings.push({
          id: uuidv4(),
          recordType: 'Lead',
          recordId: p.recordId,
          fieldName: p.fieldName,
          issueType: 'DOMAIN_MISMATCH',
          severity: 'MEDIUM',
          currentValue: null,
          proposedValue: p.proposedValue,
          confidence: typeof p.confidence === 'number' ? p.confidence : 0.85,
          reason: p.reason || 'AI detected company-domain alignment remediation',
          safeToApply: Boolean(p.safeToApply),
          requiresHumanApproval: true
        });
      }
    }
  } catch (err) {
    // Silently continue with rule findings
  }
}

// Tổng hợp thống kê
const issuesByType = {};
const issuesBySeverity = {};
let duplicatesFound = 0;
let safeToApplyCount = 0;

for (const f of allFindings) {
  issuesByType[f.issueType] = (issuesByType[f.issueType] || 0) + 1;
  issuesBySeverity[f.severity] = (issuesBySeverity[f.severity] || 0) + 1;
  if (f.issueType === 'DUPLICATE_CANDIDATE') duplicatesFound++;
  if (f.safeToApply) safeToApplyCount++;
}

const summary = {
  totalLeadsScanned: prep.totalLeadsScanned || 0,
  totalIssuesFound: allFindings.length,
  issuesByType,
  issuesBySeverity,
  duplicatesFound,
  safeToApplyCount
};

return [{
  json: {
    workflowRunId: prep.workflowRunId,
    status: 'SUCCESS',
    summary,
    findings: allFindings
  }
}];
